-- Phase 8: catalogue search (D-081 as amended by Q8-1; database-design.md §3.1).
-- The column and the three indexes are generated by `prisma migrate diff
-- --from-schema <Phase 7 schema> --to-schema prisma/schema.prisma`. The
-- extension, functions, triggers and backfill are handwritten: Prisma does not
-- model them and its drift check does not notice if one is removed, so
-- apps/api/src/db/handwritten.ts lists them and tests check them.

-- Trigram operators for typo-tolerant suggestions. Must exist before the
-- gin_trgm_ops indexes below.
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

-- AlterTable
ALTER TABLE "product" ADD COLUMN     "search_vector" tsvector NOT NULL DEFAULT ''::tsvector;

-- CreateIndex
CREATE INDEX "category_name_trgm_idx" ON "category" USING GIN ("name" gin_trgm_ops);

-- CreateIndex
CREATE INDEX "product_search_vector_idx" ON "product" USING GIN ("search_vector");

-- CreateIndex
CREATE INDEX "product_name_trgm_idx" ON "product" USING GIN ("name" gin_trgm_ops);

-- Search document for one product, `simple` configuration so transliterated
-- garment names are not stemmed as English. Weights:
--   A  product name;
--   B  category name, collection names, names of the colours of the
--      product's active variants (an inactive variant's colour is not
--      searchable; system-design.md §1);
--   C  short description and the "text" values of the structured rich-text
--      description (Q8-10). The lookup is silent: unexpected JSON yields no
--      text instead of an error, so it can never block saving a product.
CREATE FUNCTION "product_search_document"("p_id" UUID) RETURNS tsvector
  LANGUAGE sql STABLE AS $$
  SELECT
    setweight(to_tsvector('simple', coalesce(p."name", '')), 'A') ||
    setweight(to_tsvector('simple', coalesce(c."name", '')), 'B') ||
    setweight(to_tsvector('simple', coalesce((
      SELECT string_agg(col."name", ' ' ORDER BY col."name")
      FROM "collection_product" cp
      JOIN "collection" col ON col."id" = cp."collection_id"
      WHERE cp."product_id" = p."id"), '')), 'B') ||
    setweight(to_tsvector('simple', coalesce((
      SELECT string_agg(DISTINCT co."name", ' ')
      FROM "product_variant" v
      JOIN "colour" co ON co."id" = v."colour_id"
      WHERE v."product_id" = p."id" AND v."is_active"), '')), 'B') ||
    setweight(to_tsvector('simple', coalesce(p."short_description", '') || ' ' || coalesce((
      SELECT string_agg(t #>> '{}', ' ')
      FROM jsonb_path_query(p."description", 'strict $.**.text', '{}', true) AS t
      WHERE jsonb_typeof(t) = 'string'), '')), 'C')
  FROM "product" p
  JOIN "category" c ON c."id" = p."category_id"
  WHERE p."id" = "p_id"
$$;

-- Recomputes the search document for the given products. Updating only
-- "search_vector" never fires the product trigger below (it watches other
-- columns), so there is no recursion.
CREATE FUNCTION "refresh_product_search"("p_ids" UUID[]) RETURNS void
  LANGUAGE sql AS $$
  UPDATE "product" SET "search_vector" = "product_search_document"("id")
  WHERE "id" = ANY("p_ids")
$$;

-- The product's own searchable fields, or its category, changed.
CREATE FUNCTION "product_search_on_product"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  PERFORM "refresh_product_search"(ARRAY[NEW."id"]);
  RETURN NULL;
END;
$$;

-- A category was renamed: every product in it.
CREATE FUNCTION "product_search_on_category"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  PERFORM "refresh_product_search"(ARRAY(
    SELECT p."id" FROM "product" p WHERE p."category_id" = NEW."id"));
  RETURN NULL;
END;
$$;

-- A collection was renamed: every product in it.
CREATE FUNCTION "product_search_on_collection"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  PERFORM "refresh_product_search"(ARRAY(
    SELECT cp."product_id" FROM "collection_product" cp WHERE cp."collection_id" = NEW."id"));
  RETURN NULL;
END;
$$;

-- A product joined or left a collection (including through a cascade when the
-- collection is deleted).
CREATE FUNCTION "product_search_on_collection_product"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    PERFORM "refresh_product_search"(ARRAY[OLD."product_id"]);
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    PERFORM "refresh_product_search"(ARRAY[NEW."product_id"]);
  END IF;
  RETURN NULL;
END;
$$;

-- A variant was added, removed, moved, recoloured, activated or deactivated.
CREATE FUNCTION "product_search_on_variant"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    PERFORM "refresh_product_search"(ARRAY[OLD."product_id"]);
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    PERFORM "refresh_product_search"(ARRAY[NEW."product_id"]);
  END IF;
  RETURN NULL;
END;
$$;

-- A colour was renamed: every product with a variant in that colour.
CREATE FUNCTION "product_search_on_colour"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  PERFORM "refresh_product_search"(ARRAY(
    SELECT DISTINCT v."product_id" FROM "product_variant" v WHERE v."colour_id" = NEW."id"));
  RETURN NULL;
END;
$$;

CREATE TRIGGER "product_search_refresh"
  AFTER INSERT OR UPDATE OF "name", "category_id", "short_description", "description" ON "product"
  FOR EACH ROW EXECUTE FUNCTION "product_search_on_product"();
CREATE TRIGGER "category_search_refresh"
  AFTER UPDATE OF "name" ON "category"
  FOR EACH ROW WHEN (OLD."name" IS DISTINCT FROM NEW."name")
  EXECUTE FUNCTION "product_search_on_category"();
CREATE TRIGGER "collection_search_refresh"
  AFTER UPDATE OF "name" ON "collection"
  FOR EACH ROW WHEN (OLD."name" IS DISTINCT FROM NEW."name")
  EXECUTE FUNCTION "product_search_on_collection"();
CREATE TRIGGER "collection_product_search_refresh"
  AFTER INSERT OR DELETE OR UPDATE OF "collection_id", "product_id" ON "collection_product"
  FOR EACH ROW EXECUTE FUNCTION "product_search_on_collection_product"();
CREATE TRIGGER "product_variant_search_refresh"
  AFTER INSERT OR DELETE OR UPDATE OF "product_id", "colour_id", "is_active" ON "product_variant"
  FOR EACH ROW EXECUTE FUNCTION "product_search_on_variant"();
CREATE TRIGGER "colour_search_refresh"
  AFTER UPDATE OF "name" ON "colour"
  FOR EACH ROW WHEN (OLD."name" IS DISTINCT FROM NEW."name")
  EXECUTE FUNCTION "product_search_on_colour"();

-- Backfill existing products.
UPDATE "product" SET "search_vector" = "product_search_document"("id");
